def apply_rule_vscan(grid,color,fillcolor=2):
 out=[row[:] for row in grid]
 rows,cols=len(grid),len(grid[0])
 # For each fixed v=r-c, list color-pixel diagonal values u=r+c.
 byv=defaultdict(set)
 for r in range(rows):
  for c in range(cols):
   if grid[r][c]==color: byv[r-c].add(r+c)
 for v, us in byv.items():
  us=sorted(us)
  # Fill between each consecutive diagonal crossing at this v
  for u1,u2 in zip(us,us[1:]):
   for u in range(u1+1,u2):
    if (u+v)%2: continue
    r=(u+v)//2; c=(u-v)//2
    if 0<=r<rows and 0<=c<cols and out[r][c]==8: out[r][c]=fillcolor
 return out
